From 198961512733bd92f43cf530c66aa142e92409c8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:31:56 +0100
Subject: [PATCH] formatter: show temperatures in Fahrenheit for US measurement
 units

Temperatures were always shown in Celsius, even when the region settings
use US measurement units. Now they are converted to Fahrenheit in that
case, while chart range settings keep using Celsius as they are stored.

BUG: 466917
---
 formatter/Formatter.cpp     | 15 +++++++++++++--
 sensors/SensorUnitModel.cpp |  5 ++++-
 2 files changed, 17 insertions(+), 3 deletions(-)

diff --git a/formatter/Formatter.cpp b/formatter/Formatter.cpp
index e42210be..11dbfab5 100644
--- a/formatter/Formatter.cpp
+++ b/formatter/Formatter.cpp
@@ -44,6 +44,11 @@ static KFormat::BinaryUnitDialect binaryDialect()
     return dialect;
 }

+static bool useFahrenheit()
+{
+    return QLocale().measurementSystem() == QLocale::ImperialUSSystem;
+}
+
 static KLocalizedString unitFormat(Unit unit)
 {
     // The strings here use \u200B (zero-width space) to allow the unit symbol
@@ -198,6 +203,8 @@ static KLocalizedString unitFormat(Unit unit)
     const static KLocalizedString RPM = ki18nc("Revolutions per minute unit symbol", "%1\u2009RPM");
     // i18n: Use \u2009 (thin space)  to separate value and unit
     const static KLocalizedString C = ki18nc("Celsius unit symbol", "%1\u2009°C");
+    // i18n: Use \u2009 (thin space)  to separate value and unit
+    const static KLocalizedString F = ki18nc("Fahrenheit unit symbol", "%1\u2009°F");
     // i18n: Use \u2009 (thin space) to separate value and unit
     const static KLocalizedString dBm = ki18nc("Decibels unit symbol", "%1\u2009dBm");
     // i18n: Use \u200B (zero width space) to separate value and unit
@@ -314,7 +321,7 @@ static KLocalizedString unitFormat(Unit unit)
         return PA;

     case UnitCelsius:
-        return C;
+        return useFahrenheit() ? F : C;
     case UnitDecibelMilliWatts:
         return dBm;
     case UnitPercent:
@@ -513,6 +520,10 @@ static QString formatNumber(const QVariant &value, Unit unit, MetricPrefix prefi
         return QString();
     }

+    if (unit == UnitCelsius && useFahrenheit()) {
+        amount = amount * 9.0 / 5.0 + 32.0;
+    }
+
     const Unit adjusted = adjustedUnit(amount, unit, prefix);
     if (adjusted != unit) {
         amount /= std::pow(unitOrder(unit), adjusted - unit);
@@ -773,7 +784,7 @@ QString Formatter::symbol(Unit unit)
     case UnitRpm:
         return i18nc("Revolutions per minute unit symbol", "RPM");
     case UnitCelsius:
-        return i18nc("Celsius unit symbol", "°C");
+        return useFahrenheit() ? i18nc("Fahrenheit unit symbol", "°F") : i18nc("Celsius unit symbol", "°C");
     case UnitDecibelMilliWatts:
         return i18nc("Decibels unit symbol", "dBm");
     case UnitSecond:
diff --git a/sensors/SensorUnitModel.cpp b/sensors/SensorUnitModel.cpp
index 393cdb7b..43c44d3b 100644
--- a/sensors/SensorUnitModel.cpp
+++ b/sensors/SensorUnitModel.cpp
@@ -11,6 +11,8 @@

 #include <QScopeGuard>

+#include <KLocalizedString>
+
 #include "formatter/Formatter.h"
 #include "formatter/Unit.h"
 #include "systemstats/SensorInfo.h"
@@ -175,7 +177,8 @@ void SensorUnitModel::metaDataChanged(const QString &id, const SensorInfo &info)

     UnitInfo unitInfo;
     unitInfo.unit = unit;
-    unitInfo.symbol = Formatter::symbol(unit);
+    // Ranges are stored in the sensor's unit, so don't show a converted temperature symbol here.
+    unitInfo.symbol = unit == UnitCelsius ? i18nc("Celsius unit symbol", "°C") : Formatter::symbol(unit);
     unitInfo.multiplier = 1.0;

     d->units.insert(unit, unitInfo);
-- 
